HTML="<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>PBF Global | Workforce Advantage</title><style>\n:root{font-family:Inter,Arial,sans-serif;color:#143047;background:#f7fafb}*{box-sizing:border-box}body{margin:0}header{background:#10283e;color:white;padding:19px max(5%,calc((100% - 1120px)/2));display:flex;align-items:center;justify-content:space-between;gap:16px}.logo{font-weight:900;letter-spacing:.08em;font-size:21px}.logo span{color:#6de4ba}nav a{color:#d4e8ed;margin-left:22px;text-decoration:none;font-size:14px}.hero{background:linear-gradient(115deg,#10283e,#174c56);color:white;padding:85px max(5%,calc((100% - 1120px)/2)) 90px}.eyebrow{color:#77edc3;font-size:13px;font-weight:800;letter-spacing:.13em;text-transform:uppercase}.hero h1{font-size:clamp(36px,5vw,64px);line-height:1.08;max-width:800px;margin:18px 0}.hero h1 em{color:#78e4c0;font-style:normal}.hero p{font-size:18px;color:#d5e5eb;line-height:1.65;max-width:650px}.btn{display:inline-block;border:0;border-radius:8px;padding:15px 24px;background:#65dbb5;color:#10283e;font-weight:800;cursor:pointer;text-decoration:none;margin-top:14px}.btn.secondary{background:white;border:1px solid #d4e2e7}.mini{font-size:13px;color:#d8e9e9;margin-top:18px}.wrap{max-width:1120px;margin:auto;padding:65px 25px}.section-title{font-size:34px;margin:0 0 12px}.muted{color:#587082;line-height:1.6}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:30px}.card{padding:26px;border:1px solid #dfebee;border-radius:13px;background:white;box-shadow:0 5px 20px #112e3c0c}.card strong{font-size:19px}.card p{color:#637987;line-height:1.6}.kicker{color:#087b68;font-size:12px;font-weight:800;letter-spacing:.1em}.assessment{background:#eaf5f1}.panel{background:white;padding:32px;border-radius:16px;max-width:800px;margin:22px auto;border:1px solid #d7e9e5;box-shadow:0 15px 35px #082b2b0c}.progress{display:flex;gap:7px;margin-bottom:25px}.progress span{height:7px;border-radius:5px;flex:1;background:#e2ebec}.progress span.active{background:#20a586}.step{display:none}.step.active{display:block}.field{margin:14px 0}.field label{display:block;font-weight:700;font-size:14px;margin-bottom:7px}.field input,.field select,.field textarea{width:100%;padding:13px;border:1px solid #c4d6dd;border-radius:8px;font:inherit;background:white}.field textarea{min-height:90px}.cols{display:grid;grid-template-columns:1fr 1fr;gap:14px}.actions{display:flex;justify-content:space-between;gap:12px;margin-top:22px}.actions button{margin-top:0}.outline{background:white;border:1px solid #bfd9d2}.notice{background:#fff9e8;color:#77520a;padding:13px 16px;border-radius:9px;font-size:14px;line-height:1.5}.checks label{display:block;padding:8px 0}.checks input{margin-right:9px}.faq details{background:white;border:1px solid #e0e8ed;padding:18px;margin:12px 0;border-radius:10px}.faq summary{font-weight:700;cursor:pointer}.faq p{color:#617b88;line-height:1.6}footer{background:#10283e;color:#d6e4e9;padding:32px 5%;text-align:center}footer small{display:block;line-height:1.7}@media(max-width:720px){header{align-items:flex-start;flex-direction:column}nav a{margin:0 16px 0 0}.hero{padding:60px 6%}.cards{grid-template-columns:1fr}.cols{grid-template-columns:1fr}.panel{padding:22px}.wrap{padding:48px 18px}}\n</style></head><body><header><div class=\"logo\">PBF<span>.</span> GLOBAL</div><nav><a href=\"#benefits\">Solutions</a><a href=\"#assessment\">Free review</a><a href=\"#faq\">Questions</a></nav></header>\n<section class=\"hero\"><div class=\"eyebrow\">Workforce Advantage · Complimentary employer assessment</div><h1>Your team deserves <em>better benefits.</em> Your business deserves a smarter way to grow.</h1><p>Discover how a professional employer organization (PEO) may help your company manage employee benefits, payroll, HR, workers' compensation, and compliance in one coordinated solution.</p><a class=\"btn\" href=\"#assessment\">Request My Free Workforce Review →</a><div class=\"mini\">✓ No obligation &nbsp; ✓ Five-minute assessment &nbsp; ✓ Complimentary review</div></section>\n<section class=\"wrap\" id=\"benefits\"><div class=\"kicker\">ONE COORDINATED APPROACH</div><h2 class=\"section-title\">More support for your people. Less complexity for you.</h2><p class=\"muted\">PBF Global connects growing employers with a structured review of current workforce costs and available PEO options. Savings and plan availability depend on the company and proposal.</p><div class=\"cards\"><article class=\"card\"><strong>Health & employee benefits</strong><p>Explore medical, dental, vision, life, and other available programs for your workforce.</p></article><article class=\"card\"><strong>Payroll & HR administration</strong><p>Review payroll processing, onboarding, employee records, and HR technology.</p></article><article class=\"card\"><strong>Compliance & risk support</strong><p>Evaluate workers' compensation and employment administration for growing and multi-state teams.</p></article></div></section>\n<section id=\"assessment\" class=\"assessment\"><div class=\"wrap\"><div class=\"kicker\" style=\"text-align:center\">COMPLIMENTARY WORKFORCE REVIEW</div><h2 class=\"section-title\" style=\"text-align:center\">Tell us about your business</h2><p class=\"muted\" style=\"text-align:center\">Explore the five-step onboarding questionnaire. Complete this short assessment to request a complimentary workforce cost and benefits review.</p><div class=\"panel\"><div class=\"notice\"><strong>Secure intake:</strong> PBF Global collects the information you provide to evaluate your request and contact you about your workforce review. Do not include SSNs, dates of birth, employee records or confidential financial documents.</div><div class=\"progress\" id=\"progress\"><span></span><span></span><span></span><span></span><span></span></div>\n<form id=\"intake\" onsubmit=\"return false\" autocomplete=\"on\">\n<div class=\"step active\"><h3>1. Company profile</h3><div class=\"field\"><label>Company name</label><input name=\"company\" maxlength=\"120\" required placeholder=\"Example Company LLC\"></div><div class=\"cols\"><div class=\"field\"><label>Industry</label><select><option value=\"\">Select industry</option><option>Professional services</option><option>Technology</option><option>Construction</option><option>Healthcare</option><option>Retail / hospitality</option><option>Other</option></select></div><div class=\"field\"><label>Website (optional)</label><input name=\"website\" maxlength=\"120\" placeholder=\"company.com\"></div></div><div class=\"field\"><label>States where employees work</label><input name=\"states\" maxlength=\"120\" placeholder=\"Maryland, DC, Virginia\"></div></div>\n<div class=\"step\"><h3>2. Your workforce</h3><div class=\"cols\"><div class=\"field\"><label>Number of W-2 employees</label><select><option>1–4</option><option>5–9</option><option>10–24</option><option>25–49</option><option>50–99</option><option>100+</option></select></div><div class=\"field\"><label>Hiring over the next 12 months?</label><select><option>Not sure</option><option>Yes, 1–5</option><option>Yes, 6+</option><option>No</option></select></div></div><div class=\"field\"><label>Workforce composition</label><select><option>Primarily full-time employees</option><option>Mix of full-time and part-time</option><option>Multi-state / remote</option></select></div></div>\n<div class=\"step\"><h3>3. Your current services</h3><div class=\"cols\"><div class=\"field\"><label>Offer group health insurance?</label><select><option>Yes</option><option>No</option><option>Evaluating</option></select></div><div class=\"field\"><label>Benefits renewal month</label><select><option>Unknown</option><option>January–March</option><option>April–June</option><option>July–September</option><option>October–December</option></select></div></div><div class=\"field\"><label>Current payroll provider</label><input name=\"payroll\" maxlength=\"120\" placeholder=\"Optional\"></div><div class=\"field\"><label>Currently use a PEO?</label><select><option>No</option><option>Yes</option><option>Unsure</option></select></div></div>\n<div class=\"step\"><h3>4. Your priorities and questions</h3><p class=\"muted\">Which issues matter most to your company?</p><div class=\"checks\"><label><input type=\"checkbox\">Improve employee benefits</label><label><input type=\"checkbox\">Evaluate total employer costs</label><label><input type=\"checkbox\">Simplify payroll / HR</label><label><input type=\"checkbox\">Support multi-state workers</label><label><input type=\"checkbox\">Workers' compensation / compliance</label></div><div class=\"field\"><label>Questions for our team</label><textarea name=\"questions\" maxlength=\"1000\" placeholder=\"What would you like to understand about PEOs?\"></textarea></div></div>\n<div class=\"step\"><h3>5. Review and next steps</h3><div class=\"cols\"><div class=\"field\"><label>Contact name</label><input name=\"contact\" maxlength=\"120\" required placeholder=\"Your name\"></div><div class=\"field\"><label>Business email</label><input name=\"email\" maxlength=\"160\" type=\"email\" required placeholder=\"you@company.com\"></div></div><div class=\"field\"><label>Best contact method</label><select><option>Email</option><option>Phone</option></select></div><div class=\"notice\">Your information will be stored for PBF Global to review and respond to your request. Do not submit individual employee records, Social Security numbers, or confidential financial documents. See our privacy notice below.<div class=\"checks\"><label><input type=\"checkbox\" id=\"consent\"> I agree to be contacted by PBF Global about my requested workforce review and understand that the business and contact information I submit will be stored for follow-up.</label></div><div class=\"field\" style=\"position:absolute;left:-9999px\" aria-hidden=\"true\"><label>Leave blank<input id=\"company_fax\" tabindex=\"-1\" autocomplete=\"off\"></label></div><p id=\"submit-status\" role=\"status\"></p></div></div>\n<div class=\"actions\"><button type=\"button\" id=\"back\" class=\"btn outline\" onclick=\"go(-1)\">← Back</button><button type=\"button\" id=\"next\" class=\"btn\" onclick=\"go(1)\">Continue →</button></div></form></div></div></section>\n<section class=\"wrap faq\" id=\"faq\"><div class=\"kicker\">FREQUENTLY ASKED QUESTIONS</div><h2 class=\"section-title\">Questions employers ask</h2><details><summary>What is a PEO?</summary><p>A professional employer organization provides services such as HR support, payroll administration and access to certain employee benefits through a contractual co-employment arrangement.</p></details><details><summary>Do I lose control of my business or employees?</summary><p>No. The company generally retains day-to-day control of its employees and business operations. The PEO's responsibilities are defined in the service agreement.</p></details><details><summary>Will a PEO lower costs?</summary><p>Potential savings are not guaranteed. A workforce cost review compares the total costs, services and available benefits to help you decide.</p></details><details><summary>Who is a good fit?</summary><p>Growing employers with five or more employees, complex HR or benefits requirements, or employees across multiple states may benefit from a review.</p></details><details><summary>Is this an official Industrious service?</summary><p>No. PBF Global offers this independent program to interested employers, including Industrious members. Industrious does not sponsor or endorse this service.</p></details></section><footer><strong>PBF GLOBAL · WORKFORCE ADVANTAGE</strong><small>909 Rose Avenue, Suite 400 · North Bethesda, MD<br>Independent PBF Global service. Not affiliated with or endorsed by Industrious. <a href=\"/privacy\" style=\"color:#9ee4cd\">Privacy notice</a>.<br>© 2026 PBF Global, LLC. All rights reserved.</small></footer><script>\nlet step=0;function go(d){if(step===4&&d>0){submitLead();return;}step=Math.max(0,Math.min(4,step+d));document.querySelectorAll('.step').forEach((n,i)=>n.classList.toggle('active',i===step));document.querySelectorAll('#progress span').forEach((n,i)=>n.classList.toggle('active',i<=step));document.getElementById('back').style.visibility=step===0?'hidden':'visible';let b=document.getElementById('next');b.textContent=step===4?'Submit my review request':'Continue →';b.disabled=false;b.style.opacity=1;}go(0);\nasync function submitLead(){const s=document.getElementById('submit-status'), b=document.getElementById('next');s.textContent='';\nconst x=document.querySelectorAll('.step');const field=(i,j)=>x[i].querySelectorAll('input:not([type=checkbox]),select,textarea')[j]?.value.trim()||'';\nconst data={company:field(0,0),industry:field(0,1),website:field(0,2),states:field(0,3),employees:field(1,0),hiring:field(1,1),workforce:field(1,2),health:field(2,0),renewal:field(2,1),payroll:field(2,2),existing_peo:field(2,3),priorities:Array.from(x[3].querySelectorAll('input[type=checkbox]:checked')).map(i=>i.parentElement.textContent.trim()),questions:field(3,0),contact:field(4,0),email:field(4,1),contact_method:field(4,2),consent:document.getElementById('consent').checked,hp:document.getElementById('company_fax').value};\nif(!data.company||!data.contact||!data.email||!data.email.includes('@')||!data.consent){s.textContent='Please enter your company, contact name, valid email and agree to the consent statement.';s.style.color='#a33';return;}\nb.disabled=true;b.textContent='Submitting…';try{const r=await fetch('/api/leads',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data),credentials:'same-origin'});const j=await r.json();if(!r.ok)throw Error(j.error||'Request failed');document.getElementById('intake').innerHTML='<h3>Request received</h3><p>Thank you. PBF Global has received your Workforce Advantage review request. Our team will contact you using your preferred method.</p><p>Reference: '+String(j.reference).replace(/[^a-zA-Z0-9-]/g,'')+'</p>';}catch(e){s.textContent=e.message||'Submission unavailable. Please try again.';s.style.color='#a33';b.disabled=false;b.textContent='Submit my review request';}}\n</script></body></html>"
PRIVACY="<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Privacy Notice | PBF Global Workforce Advantage</title><style>body{font:16px/1.7 Arial,sans-serif;max-width:760px;margin:auto;padding:36px 22px;color:#183347}h1{line-height:1.2}a{color:#0d7e6e}</style></head><body><a href=\"/\">← Back to Workforce Advantage</a><h1>Workforce Advantage — Privacy Notice</h1><p>Effective November 7, 2026</p><p>PBF Global, LLC collects the business and contact information that you voluntarily provide through its Workforce Advantage review questionnaire. This may include company name, industry, employee-count range, work locations, benefit and payroll arrangements, business priorities, contact name and email, and your questions.</p><p>We use this information to review your inquiry and contact you about the requested workforce-cost and employee-benefits consultation. Submission does not create a client relationship or guarantee PEO eligibility, insurance terms, or savings.</p><p>Submissions are stored in an access-restricted database hosted by Railway. Access to the prospect dashboard requires administrator authentication. We do not automatically send the submitted questionnaire to a PEO or insurance provider. If further information is needed, we will coordinate the next steps with you.</p><p>Do not enter Social Security numbers, dates of birth, employee-level records, medical information, or banking details into this introductory form.</p><p>For questions, correction or removal requests, contact PBF Global through your existing business contact channel. This notice should be reviewed and approved by PBF Global before broad marketing distribution.</p></body></html>"
SCHEMA="""CREATE TABLE IF NOT EXISTS leads (id UUID PRIMARY KEY, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),company TEXT NOT NULL,industry TEXT,website TEXT,states TEXT,employees TEXT,hiring TEXT,workforce TEXT,health TEXT,renewal TEXT,payroll TEXT,existing_peo TEXT,priorities JSONB,questions TEXT,contact TEXT NOT NULL,email TEXT NOT NULL,contact_method TEXT,consent_at TIMESTAMPTZ NOT NULL DEFAULT NOW())"""
def connect():
 url=os.getenv('DATABASE_URL')
 if not url: raise RuntimeError('Database not configured')
 return psycopg.connect(url,connect_timeout=5)
def auth(header,user,pwd):
 if not user or not pwd:return False
 expected='Basic '+base64.b64encode((user+':'+pwd).encode()).decode()
 return hmac.compare_digest(header or '',expected)
class Handler(BaseHTTPRequestHandler):
 def log_message(self,fmt,*args):
  if not self.path.startswith('/api/'): super().log_message(fmt,*args)
 def send(self,status,content,ctype='text/html; charset=utf-8'):
  payload=content.encode()
  self.send_response(status)
  for k,v in [('Content-Type',ctype),('Content-Length',str(len(payload))),('Cache-Control','no-store'),('X-Content-Type-Options','nosniff'),('X-Frame-Options','DENY'),('Referrer-Policy','no-referrer'),('Content-Security-Policy',"default-src 'self' 'unsafe-inline'; connect-src 'self'; form-action 'self'; frame-ancestors 'none'")]:self.send_header(k,v)
  self.end_headers();self.wfile.write(payload)
 def challenge(self,admin=False):
  self.send_response(401);self.send_header('WWW-Authenticate','Basic realm="'+('PBF Administration' if admin else 'PBF Private Preview')+'"');self.send_header('Cache-Control','no-store');self.end_headers()
 def preview_auth(self):
  return auth(self.headers.get('Authorization'),os.getenv('PREVIEW_USER','pbf-preview'),os.getenv('PREVIEW_PASSWORD',''))
 def admin_auth(self):
  return auth(self.headers.get('Authorization'),os.getenv('ADMIN_USER','admin'),os.getenv('ADMIN_PASSWORD',''))
 def do_GET(self):
  path=urlsplit(self.path).path
  if path=='/health':
   try:
    with connect() as conn:conn.execute('SELECT 1')
    self.send(200,'ok','text/plain');return
   except Exception:self.send(503,'unavailable','text/plain');return
  if path=='/privacy':
   self.send(200,PRIVACY);return
  if path=='/admin':
   if not self.admin_auth():self.challenge(True);return
   try:
    with connect() as conn:
     conn.execute(SCHEMA)
     rows=conn.execute('SELECT created_at,company,contact,email,employees,industry,states,health,renewal,priorities,questions FROM leads ORDER BY created_at DESC LIMIT 200').fetchall()
    esc=lambda v:htmlmod.escape(str(v or ''))
    body='<h1>PBF Global — Workforce Leads</h1><p>Restricted administrator view · last 200 inquiries</p><table border="1" cellpadding="8"><tr><th>Received (UTC)</th><th>Company</th><th>Contact</th><th>Email</th><th>Employees</th><th>Industry</th><th>States</th><th>Insurance</th><th>Renewal</th><th>Priorities</th><th>Questions</th></tr>'+''.join('<tr>'+''.join('<td>'+esc(v)+'</td>' for v in row)+'</tr>' for row in rows)+'</table>'
    self.send(200,'<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>PBF Leads</title></head><body style="font:15px Arial;padding:24px;overflow-x:auto">'+body+'</body></html>');return
   except Exception:self.send(503,'Lead dashboard temporarily unavailable');return
  if path=='/':
   self.send(200,HTML);return
  self.send(404,'Not found','text/plain')
 def do_POST(self):
  if urlsplit(self.path).path!='/api/leads':self.send(404,'Not found','text/plain');return
  origin=self.headers.get('Origin','')
  host=self.headers.get('Host','')
  if not origin or origin not in ('https://'+host,'http://'+host):self.send(403,json.dumps({'error':'Invalid origin'}),'application/json');return
  if not self.headers.get('Content-Type','').startswith('application/json'):self.send(415,json.dumps({'error':'JSON required'}),'application/json');return
  try:
   size=int(self.headers.get('Content-Length','0'))
   if size<2 or size>12000:raise ValueError('Invalid request size')
   d=json.loads(self.rfile.read(size))
   if not isinstance(d,dict):raise ValueError('Invalid data')
   val=lambda k,n=160:str(d.get(k,'') or '').strip()[:n]
   company=val('company',120);contact=val('contact',120);email=val('email',160)
   if not company or not contact or not re.fullmatch(r'[^\s@]+@[^\s@]+\.[^\s@]+',email):raise ValueError('Valid company, contact and email are required')
   if d.get('consent') is not True:raise ValueError('Consent required')
   if d.get('hp'):self.send(200,json.dumps({'reference':'received'}),'application/json');return
   priorities=d.get('priorities',[])
   if not isinstance(priorities,list):raise ValueError('Invalid priorities')
   priorities=[str(x)[:100] for x in priorities[:10]]
   lid=str(uuid.uuid4())
   with connect() as conn:
    conn.execute(SCHEMA)
    conn.execute('INSERT INTO leads (id,company,industry,website,states,employees,hiring,workforce,health,renewal,payroll,existing_peo,priorities,questions,contact,email,contact_method) VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s::jsonb,%s,%s,%s,%s)',(lid,company,val('industry'),val('website'),val('states'),val('employees'),val('hiring'),val('workforce'),val('health'),val('renewal'),val('payroll'),val('existing_peo'),json.dumps(priorities),val('questions',1000),contact,email,val('contact_method')))
   self.send(201,json.dumps({'reference':lid[:8]}),'application/json')
  except ValueError as e:self.send(400,json.dumps({'error':str(e)}),'application/json')
  except Exception:self.send(503,json.dumps({'error':'Service temporarily unavailable. Please retry later.'}),'application/json')
ThreadingHTTPServer(('0.0.0.0',int(os.getenv('PORT','8000'))),Handler).serve_forever()
